package com.orbisarcana.client.circle;

import java.util.List;

import com.orbisarcana.OrbisArcana;
import com.orbisarcana.school.Schools;

import net.minecraft.resources.Identifier;

/**
 * Regions of the circle atlas generated by {@code tools/circles.cjs} (2048x2048, white with alpha, tinted per vertex).
 * Keep in sync with the layout comment at the top of that script.
 */
final class CircleAtlas {
    static final Identifier TEXTURE = OrbisArcana.id("textures/effect/circle_atlas.png");
    private static final float PX = 1f / 2048f;

    /** Plate cells: the ten built-in schools, then the rarity ornament and the dominant seal. */
    private static final List<Identifier> PLATE_ORDER = List.of(Schools.FIRE, Schools.EARTH, Schools.WATER, Schools.AIR, Schools.ICE,
            Schools.LIGHTNING, Schools.NATURE, Schools.LIGHT, Schools.DARK, Schools.ASTRAL);
    static final int ORNAMENT = 10, SEAL = 11;
    /** Fraction of a plate cell covered by its drawing (outer rim radius 244 of 256). */
    static final float PLATE_FILL = 244f / 256f;

    /** Plate index of a school; addon schools use the astral plate. */
    static int plate(Identifier school) {
        int i = PLATE_ORDER.indexOf(school);
        return i < 0 ? 9 : i;
    }

    static float plateU0(int index) { return (index % 4) * 512 * PX; }
    static float plateV0(int index) { return (index / 4) * 512 * PX; }
    static final float PLATE_SIZE = 512 * PX;

    /** Horizontal strips spanning the atlas width: {@code repeatsPerStrip} tiles, each {@code aspect} times as wide as tall. */
    record Strip(float v0, float v1, int repeatsPerStrip, float aspect) {}

    static final Strip RUNES_A = new Strip(1536 * PX, 1600 * PX, 32, 1f);
    static final Strip RUNES_B = new Strip(1600 * PX, 1664 * PX, 32, 1f);
    static final Strip TUBE = new Strip(1664 * PX, 1696 * PX, 1, 64f);
    static final Strip FILIGREE = new Strip(1696 * PX, 1744 * PX, 16, 128f / 48f);
    static final Strip TICKS = new Strip(1744 * PX, 1776 * PX, 64, 1f);

    /** One glyph cell of rune band A (64x64), for single floating runes. */
    static float glyphU0(int glyph) { return Math.floorMod(glyph, 32) * 64 * PX; }
    static final float GLYPH_V0 = 1536 * PX, GLYPH_SIZE = 64 * PX;

    static final float FLARE_U0 = 0, FLARE_V0 = 1792 * PX, SPRITE_SIZE = 128 * PX;
    static final float SPARKLE_U0 = 128 * PX;

    /** Middle of the tube profile, for solid lines that only need the bright core. */
    static final float TUBE_U = 0.5f;

    private CircleAtlas() {}
}
